{
  "name": "@doyzheng/ezllm-codebuddy-ide-auth",
  "version": "0.3.2",
  "description": "CodeBuddy IDE 登录态插件：把 JetBrains / IntelliJ 里 CodeBuddy 插件的登录凭据直接当上游账号用（每请求实时读 secret-storage.xml，不落盘、不刷新）",
  "license": "MIT",
  "type": "module",
  "main": "src/index.mjs",
  "exports": {
    ".": "./src/index.mjs"
  },
  "ezllmPlugin": true,
  "files": [
    "src/*.mjs",
    "README.md"
  ],
  "repository": {
    "type": "git",
    "url": "https://gitee.com/doyzheng/ezllm",
    "directory": "packages/plugins/codebuddy-ide"
  },
  "keywords": [
    "ezllm",
    "plugin",
    "codebuddy",
    "ide",
    "opencode"
  ],
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  },
  "scripts": {
    "check:types": "ezn tsc --noEmit",
    "test": "ezn vitest run",
    "test:coverage": "ezn vitest run --coverage",
    "release": "tsx scripts/release.ts",
    "release:checks": "tsx scripts/release.ts --checks"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "@vitest/coverage-v8": "5.0.1",
    "ezllm-logger": "workspace:*",
    "ezllm-release-kit": "workspace:*",
    "tsx": "^4.23.12",
    "typescript": "^7.0.2",
    "vitest": "^5.0.1"
  }
}
